brute_force_solution:
def constrainedSubsetSum(nums, k):
    n = len(nums)
    dp = [0] * n
    for i in range(n):
        dp[i] = nums[i] + max([0] + [dp[j] for j in range(max(0, i - k), i)])
    return max(dp)

